\label{thm:BM2}
Under the identification \eqref{eq:theta},
the boundaries $\partial \operatorname{Mov}(M_H(v))$ of $\operatorname{Mov}(M_H(v))$ are defined by $u^\perp$, where
$u \in H^*(X,{\mathbb Z})_{\operatorname{alg}}$ satisfies one of the following conditions.
\begin{enumerate}
\item
$\langle u^2 \rangle=0$ and $\langle v,u \rangle=1,2$.   
\item
$\langle u^2 \rangle=-2$ and $\langle u,v \rangle=0$.
\end{enumerate}

For the Mukai vector $v$ and $\gamma \in \operatorname{NS}(X)_{\mathbb Q}$,
we set
\begin{equation}
h_v:=e^{\xi/r}H=H+\frac{(\xi\cdot H)}{r} \varrho_X,\;
D_{v,\gamma}:=-re^\gamma+a_\gamma \varrho_X.
\end{equation}

\label{lem:ample}
\begin{enumerate}
\item[(1)]
$\theta_v(h_v+\epsilon D_{v,\gamma}) \in \operatorname{NS}(M_H^\gamma(v))_{\mathbb Q}$ $(0<\epsilon \ll 1)$ is ample,
\item[(2)]
$\theta_v(h_{v})$ is nef and big. In particular it is movable.
\end{enumerate}

\label{lem:mov}
Assume that $r=1,2$.
\begin{enumerate}
\item[(1)]
$\theta_v(h_v)$ defines a divisorial contraction of $M_H(v)$.
\item[(2)]
$\operatorname{Mov}(M_H(v)) \cap L$ is spanned by
$\theta_v(h_v)$ and $\theta_v(xh_v+D_{v,\gamma})$, where $x \in {\mathbb Q}$.
\end{enumerate}

\label{defn:xi}
For a Mukai vector $v>0$ and $\gamma \in \operatorname{NS}(X)_{\mathbb Q}$, 
we define a map $\xi_{v,\gamma} :{\mathbb H} \to v^\perp$ by
\begin{equation}
\begin{split}
                                                             
& \xi_{v,\gamma}(s,t):=\frac{1}{t}\mathrm{Im} \left(\langle e^{\gamma+(s-it)H},v \rangle e^{\gamma+(s+it)H} \right).
\end{split}
\end{equation}

By 
\begin{equation}
\langle e^{\gamma+(s-it)H},v \rangle =
s r(\delta \cdot H)-r\frac{s^2-t^2}{2}(H^2)-a_\gamma+itr((sH-\delta) \cdot H),
\end{equation}
we see that
\begin{equation*}
\begin{split}
& \frac{1}{t}\mathrm{Im} \left(\langle e^{\gamma+(s-it)H},v \rangle e^{\gamma+(s+it)H} \right)\\
=& \left(s r(\delta \cdot H)-r\frac{s^2-t^2}{2}(H^2)-a_\gamma \right)(H+s(H^2) \varrho_X)
+e^\gamma \left(1+sH+\frac{s^2-t^2}{2}(H^2) \varrho_X \right)r((sH-\delta) \cdot H)\\
=& \left(r \frac{s^2+t^2}{2}(H^2)-a_\gamma \right)e^\gamma (H+(\delta \cdot H)\rho_X)+
((sH-\delta) \cdot H)(r e^\gamma-a_\gamma \varrho_X)\\ 
=& \left(r \frac{s^2+t^2}{2}(H^2)-a_\gamma \right)h_v+
((-sH+\delta) \cdot H)D_{v,\gamma}.
\end{split}
\end{equation*}

\label{lem:W_u}
For a wall $W_u (\subset {\mathbb H}^0)$ defined by a Mukai vector $u$,
$\xi_{v,\gamma}^{-1}(u^\perp)=W_u$.

\label{defn:Delta}
We take a Mukai vector $v>0$ and $\gamma \in \operatorname{NS}(X)_{\mathbb Q}$.
For a general $(s,t) \in {\mathbb H}^0$ with respect to $v$,
let $\Delta_{(s,t)}$ be a connected component of $v^\perp \setminus \cup_{u \in {\mathcal U}}u^\perp$
such that  $\xi_{v,\gamma}(s,t) \in \Delta_{(s,t)}$, where 
 ${\mathcal U}$ is the set of Mukai vectors $u$ in Theorem \ref{thm:BM2}

\label{prop:stability-cond}
$$
U_-^\gamma \subset {\mathcal H}_-^\gamma \subset {\mathbb H}^0,\;
U_+^{\gamma} \subset {\mathcal H}_+^{\gamma} \subset {\mathbb H}^0.
$$

\label{lem:Phi(h)}
Assume that $a_\gamma>0$.
\begin{enumerate}
\item[(1)]
We set
$$
v':=f(v)=r'+\xi'+a'\varrho_{X'}.
$$
Then $v'>0$ with 
$$
v'=e^{\gamma'}(r/r_0 \varrho_{X'}-r\widehat{\delta}+a_\gamma r_0).
$$
In particular 
\begin{equation}\label{eq:v'}
r'=a_\gamma r_0,\;
\xi'=a_\gamma r_0 \gamma'-r\widehat{\delta},\;
a'=a_\gamma r_0 \frac{({\gamma'}^2)}{2}-r (\widehat{\delta} \cdot \gamma')+\frac{r}{r_0}.
\end{equation}
\item[(2)]
$$
h_{v'}=e^{\gamma'}(\widehat{H}-\frac{r}{a_\gamma r_0}(\delta \cdot H)\varrho_{X'}),\;
D_{v',\gamma'}=-a_\gamma r_0 e^{\gamma'}+\frac{r}{r_0}\varrho_{X'}.
$$
\item[(3)]
\begin{equation}
              
f(h_v)=-h_{v'}-\frac{(\delta \cdot H)}{a_\gamma }D_{v',\gamma'},\;
f(D_{v,\gamma})= -D_{v',\gamma'}. 
            
\end{equation}
\end{enumerate}

\label{lem:Phi(h)2}
Assume that $a_\gamma<0$ and set $v'=-f(v)$.
\begin{NB}
We set
$$
v'                         
=-f(v).
$$
Then $v'>0$ with 
$$
v'=e^{\gamma'}(-r/r_0 \varrho_{X'}+r\widehat{\delta}-a_\gamma r_0).
$$
In particular 
\begin{equation}\label{eq:v'}
r'=-a r_0,\;
\xi'=-a_\gamma r_0 \gamma'+r\widehat{\delta},\;
a'=-a_\gamma r_0 \frac{({\gamma'}^2)}{2}+r (\widehat{\delta} \cdot \gamma')-\frac{r}{r_0}.
\end{equation}
\end{NB}
\begin{enumerate}
\item[(1)]
$$
h_{v'}=e^{\gamma'}(\widehat{H}-\frac{r}{a_\gamma r_0}(\delta \cdot H)\varrho_{X'}),\;
D_{v',\gamma'}=a_\gamma r_0 e^{\gamma'}-\frac{r}{r_0}\varrho_{X'}.
$$
\item[(2)]
\begin{equation}
              
-f(h_v)=h_{v'}-\frac{(\delta \cdot H)}{a_\gamma }D_{v',\gamma'},\;
-f(D_{v,\gamma})= -D_{v',\gamma'}. 
            
\end{equation}
\end{enumerate}

\label{lem:D*Phi(h)}
Assume that $a_\gamma>0$.
For the Mukai vector $v'=f(v)$ in Lemma \ref{lem:Phi(h)}, we set 
$$
v'':=\overline{\mathcal D}_{X'} \circ f(v)=e^{\gamma'}(r/r_0 \varrho_{X'}+r\widehat{\delta}+a_\gamma r_0).
$$
\begin{enumerate}
\item[(1)]
$$
h_{v''}=e^{-\gamma'}(\widehat{H}+\frac{r}{a_\gamma r_0}(\delta \cdot H)\varrho_{X'}),\;
D_{v'',-\gamma'}=-a_\gamma r_0 e^{-\gamma'}+\frac{r}{r_0}\varrho_{X'}.
$$
\item[(2)]
\begin{equation}
              
-\overline{\mathcal D}_{X'} \circ f(h_v)=-h_{v''}+\frac{(\delta \cdot H)}{a_\gamma }D_{v'',-\gamma'},\;
-\overline{\mathcal D}_{X'} \circ f(D_{v,\gamma})= D_{v'',-\gamma'}. 
            
\end{equation}
\end{enumerate}

\label{lem:D*Phi(h)2}
Assume that $a_\gamma<0$.
For the Mukai vector $v'=f(v)$ in Lemma \ref{lem:Phi(h)}, we set 
$$
v'':=-\overline{\mathcal D}_{X'} \circ f(v)=e^{\gamma'}(-r/r_0 \varrho_{X'}-r\widehat{\delta}-a_\gamma r_0).
$$
\begin{enumerate}
\item[(1)]
$$
h_{v''}=e^{-\gamma'}(\widehat{H}+\frac{r}{a_\gamma r_0}(\delta \cdot H)\varrho_{X'}),\;
D_{v'',-\gamma'}=a_\gamma r_0 e^{-\gamma'}-\frac{r}{r_0}\varrho_{X'}.
$$
\item[(2)]
\begin{equation}
              
-\overline{\mathcal D}_{X'} \circ f(h_v)= h_{v''}+\frac{(\delta \cdot H)}{a_\gamma }D_{v'',-\gamma'},\;
-\overline{\mathcal D}_{X'} \circ f(D_{v,\gamma})= D_{v'',-\gamma'}. 
            
\end{equation}
\end{enumerate}

\label{lem:f(xi)}
Keep the notation in this subsection.
In particular $f$ is the orientation preserving Hodge isometry with $f^{-1}(\varrho_{X'})=r_0 e^\gamma$ 
$(r_0>0)$.
\begin{enumerate}
\item[(1)]
Assume that $v':=f(v)>0$.
\begin{equation}
f(\xi_{v,\gamma}(s,t))=\frac{2}{({s'}^2+{t'}^2)r_0 (H^2)}\xi_{v',\gamma'}(s',t').
\end{equation}
\item[(2)]
Assume that $v':=-f(v)>0$. 
\begin{equation}
-f(\xi_{v,\gamma}(s,t))=\frac{2}{({s'}^2+{t'}^2)r_0 (H^2)}\xi_{v',\gamma'}(s',t').
\end{equation}
\end{enumerate}

For a convenience sake of the reader, we give a proof of (1).
We note that
\begin{equation}
f(e^{\gamma+zH})=\frac{z^2(H^2)r_0}{2}e^{\gamma'+z'H'}
\end{equation}
and
\begin{equation}
\frac{1}{t}=\frac{2}{(s^2+t^2)(H^2)r_0 t'},
\end{equation}
where $z=s+it$ and $z'=s'+it'$.
Hence
\begin{equation}
\begin{split}
f(\xi_{v,\gamma}(s,t))=&\frac{z^2(H^2)r_0}{2}\frac{\overline{z}^2(H^2)r_0}{2}
\frac{2}{|z|^2 (H^2)r_0}\xi_{v',\gamma'}(s',t')\\
=& \frac{|z|^2(H^2)r_0}{2}\xi_{v',\gamma'}(s',t')\\
=& \frac{2}{|z'|^2(H^2)r_0}\xi_{v',\gamma'}(s',t').
\end{split}
\end{equation}

\label{lem:Df(xi)}
\begin{enumerate}
\item[(1)]
Assume that $v'=\overline{\mathcal D}_{X'} \circ f(v)>0$.
Then
\begin{equation}
\overline{\mathcal D}_{X'} \circ f(\xi_{v,\gamma}(s,t))=-
\frac{2}{({s'}^2+{t'}^2)(H^2)r_0}\xi_{v',-\gamma'}(-s',t').
\end{equation}
\item[(2)]
Assume that $v'=-\overline{\mathcal D}_{X'} \circ f(v)>0$. Then
\begin{equation}
-\overline{\mathcal D}_{X'} \circ f(\xi_{v,\gamma}(s,t))=-
\frac{2}{({s'}^2+{t'}^2)(H^2)r_0}\xi_{v',-\gamma'}(-s',t').
\end{equation}
\end{enumerate}

We keep the notation in subsection \ref{subsect:f}.
Assume that $a_\gamma>0$.
Then $v'>0$ and
$$
h_{v'}=e^{\gamma'}(\widehat{H}-\frac{r}{a_\gamma r_0}(\delta \cdot H)\varrho_{X'}),\;
D_{v',\gamma'}=-a_\gamma r_0 e^{\gamma'}+\frac{r}{r_0}\varrho_{X'}.
$$
By Lemma \ref{lem:Phi(h)},
we have the following representation matrix of 
$f:{\mathbb Q}h_v+{\mathbb Q}D_{v,\gamma} \to {\mathbb Q}h_{v'}+{\mathbb Q}D_{v',\gamma'}$:
$$
\begin{pmatrix}
f(h_v) & f(D_{v,\gamma})
\end{pmatrix}
=
\begin{pmatrix}
h_{v'} & D_{v',\gamma'}
\end{pmatrix}
\begin{pmatrix}
-1 & 0\\
-\frac{(\delta \cdot H)}{a_\gamma} & -1
\end{pmatrix}.
$$
We note the determinant of the matrix is 1.
\begin{NB}
\begin{equation}
\lim_{(s',t') \to (0,0)} \xi_{v',\gamma'}(s',t')=\frac{r}{r_0}\left( 
h_{D_{X'}(v')}-\frac{(\delta \cdot H)}{a_\gamma}D_{v',\gamma'} \right).
\end{equation}
\end{NB}


\begin{NB}
\begin{equation}
-{h_{v'}}^{\vee}=e^{-\gamma'}(\widehat{H}+\frac{r}{a_\gamma r_0}(\delta \cdot H)\varrho_{X'})
\end{equation}

\begin{equation}
D_{v',\gamma'}^{\vee}=D_{-\gamma'}.
\end{equation}

\begin{equation}
D_{X'} \circ \Phi^{{\mathcal E}^{\vee}}_{X \to X'}(e^{\xi/r}H)
=e^{-\gamma'}(\widehat{H}+\frac{r}{ar_0}(\delta \cdot H)\varrho_{X'})-
\frac{(\delta \cdot H)}{a_\gamma}D_{v',\gamma'}
\end{equation}
\end{NB}



(1)
Assume that $\theta_v(h_v) \in \partial \operatorname{Mov}(M_H(v))$ and
$(\delta \cdot H)<0$.
\begin{NB}
By Lemma \ref{lem:Phi(h)},
$$
\det \begin{pmatrix}
-1 & -\frac{(\delta \cdot H)}{a_\gamma}\\
0 & -1
\end{pmatrix}=1.
$$
\end{NB}
By Lemma \ref{lem:mov}, we get
$\theta_{v'}(h_{v'}) \not \in f(\operatorname{Mov}(M_H(v)))$.
Hence
$f(\operatorname{Mov}(M_H(v))) \not \subset \operatorname{Mov}(M_{H'}(v'))$.

\begin{NB}
$\langle \Phi^{{\mathcal E}^{\vee}}_{X \to X'}(xh_v+D_\gamma),\varrho_{X'} \rangle=
-\left(\frac{(\delta \cdot H)}{a}x +1 \right)a_\gamma r_0<0$, if $x<0$
\end{NB}

(2)
Assume that $\theta_{v'}(h_{v'}) \in \partial \operatorname{Mov}(M_{H'}(v'))$
and
$(\delta \cdot H)>0$.
                            
Lemma \ref{lem:mov} implies
$f(h_v)$ is not movable.
Therefore the claim holds.

\label{prop:FM1}
Let $\Phi_{X \to X'}^{{\mathcal E}^{\vee}}:{\bf D}(X) \to {\bf D}(X')$ be a Fourier-Mukai transform
such that ${\mathcal E}$ is a universal family of stable sheaves on $X$ with respect to $H$.
Assume that the cohomological transform preserves the movable cones:
\begin{equation}\label{eq:mov1}
\overline{\Phi}_{X \to X'}^{{\mathcal E}^{\vee}[k]}(\theta_v^{-1}(\operatorname{Mov}(M_H(v)))=\theta_{v'}^{-1}(\operatorname{Mov}(M_{H'}(v'))),
\end{equation}
 
where $H'$ is the ample divisor in \eqref{eq:polarization}.
Then there is an autoequivalence $\Psi:{\bf D}(X') \to {\bf D}(X')$
which acts trivially on $H^*(X,{\mathbb Z})$ and 
$\Phi:=\Psi \circ \Phi_{X \to X'}^{{\mathcal E}^{\vee}[k]}$ induces a birational map
$\varphi:M_H(v) \cdots \to M_{H'}(v')$ with a commutative diagram
\begin{equation}\label{eq:comm1}
\begin{CD}
v^\perp @>{\overline{\Phi}}>> {v'}^\perp\\
@V{\theta_v}VV @VV{\theta_{v'}}V\\
H^2(M_H(v),{\mathbb Z}) @>{\varphi_*}>> H^2(M_{H'}(v'),{\mathbb Z})
\end{CD}
\end{equation}

\label{prop:FM2}
                                    
Let $\Phi_{X \to X'}^{{\mathcal E}^{\vee}}:{\bf D}(X) \to {\bf D}(X')$ be a Fourier-Mukai transform
whose kernel is a universal family ${\mathcal E}$ of stable sheaves.
Assume that the cohomological transform preserves the movable cones:
\begin{equation}
-\overline{\mathcal D}_{X'} \circ \overline{\Phi}_{X \to X'}^{{\mathcal E}^{\vee}[k]}(\theta_v^{-1}(\operatorname{Mov}(M_H(v)))=\theta_{v'}^{-1}(\operatorname{Mov}(M_{H'}(v'))),
\end{equation}
 
where $H'$ is the ample divisor in \eqref{eq:polarization}.
Then there is an autoequivalence $\Psi:{\bf D}(X') \to {\bf D}(X')$
which acts trivially on $H^*(X,{\mathbb Z})$ and 
$\Phi:=\Psi \circ {\mathcal D}_{X'} \circ \Phi_{X \to X'}^{{\mathcal E}^{\vee}[k]}$ induces a birational map
$\varphi:M_H(v) \cdots \to M_{H'}(v')$ with a commutative diagram                   
\begin{equation}\label{eq:comm2}
\begin{CD}
v^\perp @>{-\overline{\Phi}}>> {v'}^\perp\\
@V{\theta_v}VV @VV{\theta_{v'}}V\\
H^2(M_H(v),{\mathbb Z}) @>{\varphi_*}>> H^2(M_{H'}(v'),{\mathbb Z})
\end{CD}
\end{equation}

If $r'=1$, then we may choose $H'=\widehat{H}$.
\begin{NB2}
If $r'>1$, then $H'$ and $\widehat{H}$ are different polarizations in general.
\end{NB2}

\label{thm:bir-auto2}
Let $X$ be a K3 surface and assume that there is no $(-2)$-curves.
Then birational automorphisms of $\operatorname{Hilb}_X^{\ell+1}$ are induced by (contravariant) Fourier-Mukai transforms.

Since $f_1$ and $f_2$ are isometries, we have $f_1 (v)=\pm f_2(v)$.
We set $g:=f_2^{-1} \circ f_1$. Then $g_{|v^\perp}=1_{v^\perp}$
and $g(v)=\pm v$.
Since 
\begin{equation}\label{eq:A}
A_{v^\perp} \cong A_{{\mathbb Z}v}={\mathbb Z}v^{\vee}/{\mathbb Z}v \cong{\mathbb Z}/\langle v^2 \rangle {\mathbb Z}
\end{equation}
and the action of $g$ on $v^\perp$ is trivial,
we get $g(v)=v$. Thus $g$ is the identity map.
